#!/usr/bin/env python3
"""Validation script for pipeline outputs."""

import json
import os
import sys

# Define expected outputs to validate
EXPECTED_FILES = [
    'outputs/t01_selected_indicators.csv',
    'outputs/t05_clean_stops.csv',
    'outputs/t08_pois_clean.csv',
    'outputs/t10_accessibility_scores.csv',
    'outputs/t13_city_clusters.csv'
]

# Expected column structures
EXPECTED_COLUMNS = {
    't01_selected_indicators.csv': ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction'],
    't05_clean_stops.csv': ['stop_id', 'stop_name', 'stop_lat', 'stop_lon'],
    't08_pois_clean.csv': ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source'],
    't10_accessibility_scores.csv': ['qid', 'label', 'poi_type', 'distance_m', 'n_departures', 'n_routes', 'accessibility_score'],
    't13_city_clusters.csv': ['city_id', 'city_name', 'cluster_id', 'cluster_name']
}

def check_file_exists(filepath):
    """Check if file exists."""
    return os.path.exists(filepath)

def check_file_not_empty(filepath):
    """Check if file is not empty."""
    if not os.path.exists(filepath):
        return False, "File does not exist"
    if os.path.getsize(filepath) == 0:
        return False, "File is empty"
    return True, "File exists and is not empty"

def check_file_structure(filepath, expected_columns):
    """Check if file has expected columns."""
    if not check_file_not_empty(filepath)[0]:
        return False, f"File not found or empty: {filepath}"

    try:
        import pandas as pd
        df = pd.read_csv(filepath)
        missing_columns = [col for col in expected_columns if col not in df.columns]
        if missing_columns:
            return False, f"Missing columns: {missing_columns}"
        return True, f"File has all expected columns"
    except Exception as e:
        return False, f"Error reading file: {str(e)}"

def validate_output():
    """Main validation function."""
    results = []

    for filepath in EXPECTED_FILES:
        filename = os.path.basename(filepath)

        # Check file exists
        exists, msg = check_file_exists(filepath)
        results.append({
            'check_name': f'file_exists_{filename}',
            'passed': exists,
            'message': msg if not exists else 'File exists'
        })

        if not exists:
            continue

        # Check file not empty
        not_empty, msg = check_file_not_empty(filepath)
        results.append({
            'check_name': f'file_not_empty_{filename}',
            'passed': not_empty,
            'message': msg if not not_empty else 'File is not empty'
        })

        if not not_empty:
            continue

        # Check file structure
        structure_ok, msg = check_file_structure(filepath, EXPECTED_COLUMNS[filename])
        results.append({
            'check_name': f'file_structure_{filename}',
            'passed': structure_ok,
            'message': msg if not structure_ok else 'File structure is valid'
        })

        if not structure_ok:
            continue

        # Additional checks based on file type
        if 't01_selected_indicators.csv' in filepath:
            # Check for specific values in expected_direction
            try:
                import pandas as pd
                df = pd.read_csv(filepath)
                valid_directions = ['lower_is_better', 'higher_is_better', 'no_change']
                if not all(d in valid_directions for d in df['expected_direction'].unique()):
                    results.append({
                        'check_name': f'valid_directions_{filename}',
                        'passed': False,
                        'message': 'Invalid expected_direction values found'
                    })
                else:
                    results.append({
                        'check_name': f'valid_directions_{filename}',
                        'passed': True,
                        'message': 'All expected_direction values are valid'
                    })
            except Exception as e:
                results.append({
                    'check_name': f'valid_directions_{filename}',
                    'passed': False,
                    'message': f'Error validating directions: {str(e)}'
                })

        elif 't05_clean_stops.csv' in filepath:
            # Check for valid coordinates
            try:
                import pandas as pd
                df = pd.read_csv(filepath)
                if (df['stop_lat'].abs() <= 90).all() and (df['stop_lon'].abs() <= 180).all():
                    results.append({
                        'check_name': f'valid_coordinates_{filename}',
                        'passed': True,
                        'message': 'All coordinates are within valid range'
                    })
                else:
                    results.append({
                        'check_name': f'valid_coordinates_{filename}',
                        'passed': False,
                        'message': 'Some coordinates are outside valid range'
                    })
            except Exception as e:
                results.append({
                    'check_name': f'valid_coordinates_{filename}',
                    'passed': False,
                    'message': f'Error validating coordinates: {str(e)}'
                })

        elif 't08_pois_clean.csv' in filepath:
            # Check for valid coordinates
            try:
                import pandas as pd
                df = pd.read_csv(filepath)
                if (df['latitude'].abs() <= 90).all() and (df['longitude'].abs() <= 180).all():
                    results.append({
                        'check_name': f'valid_coordinates_{filename}',
                        'passed': True,
                        'message': 'All coordinates are within valid range'
                    })
                else:
                    results.append({
                        'check_name': f'valid_coordinates_{filename}',
                        'passed': False,
                        'message': 'Some coordinates are outside valid range'
                    })
            except Exception as e:
                results.append({
                    'check_name': f'valid_coordinates_{filename}',
                    'passed': False,
                    'message': f'Error validating coordinates: {str(e)}'
                })

        elif 't10_accessibility_scores.csv' in filepath:
            # Check that accessibility_score is between 0 and 1
            try:
                import pandas as pd
                df = pd.read_csv(filepath)
                if (df['accessibility_score'] >= 0).all() and (df['accessibility_score'] <= 1).all():
                    results.append({
                        'check_name': f'valid_accessibility_scores_{filename}',
                        'passed': True,
                        'message': 'All accessibility scores are within valid range [0, 1]'
                    })
                else:
                    results.append({
                        'check_name': f'valid_accessibility_scores_{filename}',
                        'passed': False,
                        'message': 'Some accessibility scores are outside valid range [0, 1]'
                    })
            except Exception as e:
                results.append({
                    'check_name': f'valid_accessibility_scores_{filename}',
                    'passed': False,
                    'message': f'Error validating accessibility scores: {str(e)}'
                })

        elif 't13_city_clusters.csv' in filepath:
            # Check for cluster_id uniqueness
            try:
                import pandas as pd
                df = pd.read_csv(filepath)
                if df['cluster_id'].nunique() == len(df):
                    results.append({
                        'check_name': f'unique_cluster_ids_{filename}',
                        'passed': True,
                        'message': 'All cluster_ids are unique'
                    })
                else:
                    results.append({
                        'check_name': f'unique_cluster_ids_{filename}',
                        'passed': False,
                        'message': 'Some cluster_ids are duplicated'
                    })
            except Exception as e:
                results.append({
                    'check_name': f'unique_cluster_ids_{filename}',
                    'passed': False,
                    'message': f'Error validating cluster IDs: {str(e)}'
                })

    # Write results to JSON
    with open('outputs/t14_validation_summary.json', 'w') as f:
        json.dump(results, f, indent=2)

    return results

if __name__ == '__main__':
    validate_output()
```

